#include "reference_element_finalization.h"
#include <array>
#include <fstream>
#include <iostream>
#include <stdexcept>
struct Attribute{unsigned index;Attribute* next;};
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("oracle required");std::ifstream file(argv[1],std::ios::binary);unsigned cases=0;for(unsigned length=0;length<=32;++length)for(unsigned initial=0;initial<256;++initial){std::array<Attribute,32>attributes{};for(unsigned i=0;i<length;++i){unsigned index=i*17%32;attributes[index]={index,i+1<length?&attributes[(i+1)*17%32]:nullptr};}Attribute*head=length?&attributes[0]:nullptr;uint32_t mode=initial,flags=0xa5000000;std::array<uint32_t,40>actual{},expected{};finalizeRecoveredReferenceElementCandidate(head,flags,[&](){return mode;},[&](uint32_t value){if(actual[1]==0){if(value!=0)throw std::runtime_error("disable");actual[1]=1;}else{if(!(flags&0x1000))throw std::runtime_error("restore");actual[1]=2;}mode=value;},[](Attribute*a){return a->next;},[&](Attribute*a){if(mode!=0)throw std::runtime_error("destroy mode");actual[4+actual[2]++]=a->index;a->next=nullptr;},[&](uint32_t request){if(mode!=0||request!=3)throw std::runtime_error("dirty mode");++actual[3];});actual[0]=mode;actual[36]=head!=nullptr;actual[37]=flags;if(!file.read(reinterpret_cast<char*>(expected.data()),sizeof(expected))||actual!=expected)throw std::runtime_error("oracle mismatch");++cases;}char extra;if(file.get(extra))throw std::runtime_error("extra oracle");std::cout<<"x64_element_finalization_cases="<<cases<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
